import { afterEach, beforeEach, expect, test } from 'vitest';
import { bookSlot, loadActiveBookings, loadMentors, type BookingInput } from './bookings.ts';
import { buildSlots, type WorkingHours } from './slots.ts';
import { createTestDb, expectBookingRulesHold, insertMentor, type TestDb } from './test-db.ts';

let db: TestDb;
let pool: TestDb['pool'];
beforeEach(async () => {
  db = await createTestDb();
  pool = db.pool;
});
afterEach(() => db.drop());

const NOW = new Date('2026-10-20T12:00:00Z');
const hoursOn = (weekdays: number[], start: string, end: string): WorkingHours[] => weekdays.map((weekday) => ({ weekday, start, end }));
const ukHours = hoursOn([1, 2, 3, 4, 5], '20:30', '23:30');
const usHours = hoursOn([0, 2, 3, 4, 5, 6], '02:30', '07:30');
const input = (iso: string): BookingInput => ({
  startsAt: new Date(iso),
  parentName: 'Asha Patel',
  parentEmail: 'asha@example.com',
  childName: 'Rohan',
  parentTimeZone: 'Europe/London',
});
const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));
// a tiny linear congruential generator, so the burst is the same on every run
const seededPick = (seed: number) => {
  let state = seed;
  return <T>(list: T[]): T => list[Math.floor(((state = (state * 1664525 + 1013904223) % 2 ** 32) / 2 ** 32) * list.length)]!;
};

test('assigns the least-booked mentor, then the lowest id', async () => {
  const a = await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
  const b = await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
  const first = await bookSlot(pool, input('2026-10-27T15:00:00Z'), NOW);
  const second = await bookSlot(pool, input('2026-10-27T16:00:00Z'), NOW);
  expect([first, second].map((r) => r.ok && r.booking.mentorId)).toEqual([a, b]);
});

test("stores the instant and the date in the mentor's own time zone", async () => {
  await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: [{ weekday: 2, start: '02:30', end: '03:30' }] });
  const result = await bookSlot(pool, input('2026-10-26T21:00:00Z'), NOW); // Mon 9:00 PM in London = Tue 2:30 AM in Kolkata
  expect(result).toMatchObject({ ok: true, booking: { mentorLocalDate: '2026-10-27' } });
  expect(result.ok && result.booking.classLink).toMatch(/^https:\/\/classroom\.example\/trial\/[\w-]{8,}$/);
  const { rows } = await pool.query('select starts_at, mentor_local_date from bookings');
  expect([rows[0].starts_at.toISOString(), rows[0].mentor_local_date]).toEqual(['2026-10-26T21:00:00.000Z', '2026-10-27']);
});

test('cancelled bookings free both the hour and the cap', async () => {
  await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
  const first = await bookSlot(pool, input('2026-10-27T15:00:00Z'), NOW);
  await bookSlot(pool, input('2026-10-27T16:00:00Z'), NOW);
  expect(await bookSlot(pool, input('2026-10-27T17:00:00Z'), NOW)).toEqual({ ok: false, code: 'SLOT_UNAVAILABLE' });
  await pool.query('update bookings set cancelled_at = now() where id = $1', [first.ok && first.booking.id]);
  expect((await bookSlot(pool, input('2026-10-27T15:00:00Z'), NOW)).ok).toBe(true);
  expect(await loadActiveBookings(pool, NOW, new Date('2026-11-04T00:00:00Z'))).toHaveLength(2);
});

test('refuses times that cannot be booked', async () => {
  await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
  // off the hour, too soon, beyond 14 days, nobody works on Sunday
  for (const t of ['2026-10-27T15:30:00Z', '2026-10-20T13:00:00Z', '2026-11-04T15:00:00Z', '2026-10-25T15:00:00Z'])
    expect(await bookSlot(pool, input(t), NOW)).toEqual({ ok: false, code: 'SLOT_UNAVAILABLE' });
});

test('same-hour race: exactly one booking per free mentor', async () => {
  const ids = [];
  for (let i = 0; i < 3; i++) ids.push(await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours }));
  const results = await Promise.all(Array.from({ length: 10 }, () => bookSlot(pool, input('2026-10-27T16:00:00Z'), NOW)));
  const booked = results.flatMap((r) => (r.ok ? [r.booking.mentorId] : []));
  expect(booked).toHaveLength(3);
  expect(new Set(booked)).toEqual(new Set(ids));
  expect(results.filter((r) => !r.ok)).toHaveLength(7);
});

test('cap race: the lock makes the second booking wait, then refuse', async () => {
  await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
  await bookSlot(pool, input('2026-10-27T15:00:00Z'), NOW);
  const pause = { beforeInsert: () => sleep(100) };
  const results = await Promise.all([
    bookSlot(pool, input('2026-10-27T16:00:00Z'), NOW, pause),
    bookSlot(pool, input('2026-10-27T17:00:00Z'), NOW, pause),
  ]);
  expect(results.filter((r) => r.ok)).toHaveLength(1);
  const { rows } = await pool.query(`select count(*)::int as n from bookings where mentor_local_date = '2026-10-27' and cancelled_at is null`);
  expect(rows[0].n).toBe(2);
});

test('a random burst keeps every rule', async () => {
  for (let i = 0; i < 5; i++) await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
  for (let i = 0; i < 5; i++) await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: usHours });
  const mentors = await loadMentors(pool);
  const open = buildSlots(mentors, [], NOW).map((s) => s.startsAt.toISOString());
  const pick = seededPick(42);
  const results = await Promise.all(Array.from({ length: 80 }, () => bookSlot(pool, input(pick(open)), NOW)));
  expect(results.some((r) => r.ok)).toBe(true);
  await expectBookingRulesHold(pool);
});

test('orders candidates by active classes on that local day only', async () => {
  const a = await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
  await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
  await bookSlot(pool, input('2026-10-28T15:00:00Z'), NOW); // a, on another local day
  const first = await bookSlot(pool, input('2026-10-27T15:00:00Z'), NOW);
  await pool.query('update bookings set cancelled_at = now() where id = $1', [first.ok && first.booking.id]);
  const next = await bookSlot(pool, input('2026-10-27T16:00:00Z'), NOW);
  expect([first, next].map((r) => r.ok && r.booking.mentorId)).toEqual([a, a]); // neither the other day nor the cancelled row counts
});

import express, { type Express, type NextFunction, type Request, type Response } from 'express';
import type pg from 'pg';
import { z } from 'zod';
import type { ApiErrorBody, BookingDto, ErrorCode, MentorsResponse, SlotsResponse } from '../shared/types.ts';
import { isValidTimeZone } from '../shared/time.ts';
import { bookSlot, getBookingWithMentor, loadActiveBookings, loadMentors, type Booking } from './bookings.ts';
import { renderEmails, type Mailer } from './email.ts';
import { buildSlots, CLASS_MINUTES, type Mentor } from './slots.ts';

export type Clock = { now: () => Date; demo: boolean };

const HOUR_MS = 3_600_000;
const DAY_MS = 24 * HOUR_MS;
const END_OF_TIME = new Date('9999-12-31T00:00:00Z');

/** The only reader of the real time. A DEMO_NOW makes the clock start there and keep ticking. */
export function createClock(demoNow: string | undefined, realNow: () => number = Date.now): Clock {
  if (!demoNow) return { now: () => new Date(realNow()), demo: false };
  // Date.parse alone accepts 'Oct 20 2026' and reads a time with no offset in the host zone
  if (!z.iso.datetime({ offset: true }).safeParse(demoNow).success) throw new Error('DEMO_NOW must be an ISO instant');
  const offset = Date.parse(demoNow) - realNow();
  return { now: () => new Date(realNow() + offset), demo: true };
}

const name = z.string().trim().min(1, 'Required').max(80).regex(/^[^\p{Cc}\p{Zl}\p{Zp}]*$/u, 'No line breaks or control characters');
const bookingBody = z.object({
  startsAt: z.iso.datetime({ offset: true }).transform((s) => new Date(s)).refine((d) => d.getTime() % HOUR_MS === 0, 'Must start on the UTC hour'),
  parentName: name,
  parentEmail: z.email().max(254),
  childName: name,
  parentTimeZone: z.string().max(64).refine(isValidTimeZone, 'Unknown time zone'),
});

const STATUS: Record<ErrorCode, number> = { VALIDATION_FAILED: 400, SLOT_UNAVAILABLE: 409, NOT_FOUND: 404, INTERNAL: 500 };
const fail = (res: Response, code: ErrorCode, message: string, fields?: Record<string, string>): void => {
  res.status(STATUS[code]).json({ error: { code, message, fields } } satisfies ApiErrorBody);
};

const toDto = ({ booking: b, mentor: m }: { booking: Booking; mentor: Mentor }): BookingDto => ({
  id: b.id,
  startsAt: b.startsAt.toISOString(),
  endsAt: new Date(b.startsAt.getTime() + CLASS_MINUTES * 60_000).toISOString(),
  childName: b.childName,
  parentName: b.parentName,
  parentEmail: b.parentEmail,
  parentTimeZone: b.parentTimeZone,
  classLink: b.classLink,
  mentor: { name: m.name, bio: m.bio, subjects: m.subjects, timeZone: m.timeZone },
});

export function createApp(deps: {
  pool: pg.Pool;
  clock: Clock;
  mailer: Mailer;
  appUrl: string;
  webDir?: string;
  log?: (message: string, error?: unknown) => void;
}): Express {
  const { pool, clock, mailer, appUrl, webDir, log = console.error } = deps;
  const app = express();
  app.disable('x-powered-by');

  app.use('/api', (_req, res, next) => {
    res.set('Cache-Control', 'no-store');
    next();
  });
  app.use(express.json());

  app.get('/api/slots', async (_req, res) => {
    const now = clock.now();
    // wide margins, so earlier bookings that still count toward a mentor's day are included
    const [mentors, bookings] = await Promise.all([loadMentors(pool), loadActiveBookings(pool, new Date(now.getTime() - 2 * DAY_MS), new Date(now.getTime() + 16 * DAY_MS))]);
    const slots = buildSlots(mentors, bookings, now).map((s) => ({ startsAt: s.startsAt.toISOString(), available: s.available }));
    res.json({ now: now.toISOString(), demo: clock.demo, slots } satisfies SlotsResponse);
  });

  app.post('/api/bookings', async (req, res) => {
    const input = bookingBody.parse(req.body ?? {});
    const result = await bookSlot(pool, input, clock.now());
    if (!result.ok) return fail(res, 'SLOT_UNAVAILABLE', 'That time is no longer available. Please pick another.');
    const found = await getBookingWithMentor(pool, result.booking.id);
    if (!found) throw new Error(`booking ${result.booking.id} is missing right after it was made`);
    res.status(201).json({ booking: toDto(found) });

    // after the response, so a mail failure never fails a booking; the catch keeps a render error away from Express's default handler
    try {
      const { parent, mentor } = renderEmails({ ...found.booking, mentor: found.mentor }, appUrl);
      const sends = await Promise.allSettled([parent, mentor].map(async (message) => mailer.send(message)));
      for (const send of sends) if (send.status === 'rejected') log('could not send a booking email', send.reason);
    } catch (err) {
      log('could not prepare the booking emails', err);
    }
  });

  app.get('/api/bookings/:id', async (req, res) => {
    const id = z.uuid().safeParse(req.params.id); // a malformed id would make Postgres throw
    const found = id.success ? await getBookingWithMentor(pool, id.data) : null;
    if (!found) return fail(res, 'NOT_FOUND', 'No such booking.');
    res.json({ booking: toDto(found) });
  });

  app.get('/api/mentors', async (_req, res) => {
    const now = clock.now();
    const [mentors, bookings] = await Promise.all([loadMentors(pool), loadActiveBookings(pool, now, END_OF_TIME)]);
    bookings.sort((a, b) => a.startsAt.getTime() - b.startsAt.getTime());
    res.json({
      now: now.toISOString(),
      demo: clock.demo,
      mentors: mentors.map((m) => ({
        id: m.id,
        name: m.name,
        bio: m.bio,
        subjects: m.subjects,
        timeZone: m.timeZone,
        bookings: bookings.filter((b) => b.mentorId === m.id).map((b) => ({ startsAt: b.startsAt.toISOString() })),
      })),
    } satisfies MentorsResponse);
  });

  app.use('/api', (_req, res) => fail(res, 'NOT_FOUND', 'No such endpoint.'));

  if (webDir) {
    app.use(express.static(webDir));
    app.get('/{*splat}', (_req, res) => res.sendFile('index.html', { root: webDir }));
  }

  app.use((err: unknown, _req: Request, res: Response, next: NextFunction) => {
    if (res.headersSent) return next(err);
    if (err instanceof z.ZodError) {
      const fields: Record<string, string> = {};
      for (const issue of err.issues) fields[issue.path.join('.')] ??= issue.message;
      return fail(res, 'VALIDATION_FAILED', 'Some details need fixing.', fields);
    }
    // body-parser's client errors (bad JSON, too large, unknown encoding) carry a string type and a 4xx status; sendFile's ENOENT has only a status
    const { type, status } = err as { type?: unknown; status?: unknown };
    if (typeof type === 'string' && typeof status === 'number' && status >= 400 && status < 500) {
      return fail(res, 'VALIDATION_FAILED', type === 'entity.parse.failed' ? 'The request body is not valid JSON.' : 'The request could not be read.');
    }
    log('unhandled error', err);
    fail(res, 'INTERNAL', 'Something went wrong. Please try again.');
  });

  return app;
}
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { createApp, createClock } from './app.ts';
import { createPool, migrate } from './db.ts';
import { createSmtpMailer } from './email.ts';
import { seed } from './seed.ts';

const { DATABASE_URL = 'postgres://bookings:bookings@localhost:5433/bookings', SMTP_URL = 'smtp://localhost:1025', APP_URL = 'http://localhost:3000', PORT = '3000', DEMO_NOW } = process.env;

const clock = createClock(DEMO_NOW);
const pool = createPool(DATABASE_URL);
await migrate(pool);
await seed(pool, clock.now());

// the web build arrives with the front end; until `dist/web/index.html` exists the server is API-only
const webDir = new URL('../../dist/web/', import.meta.url);
const app = createApp({
  pool,
  clock,
  mailer: createSmtpMailer(SMTP_URL),
  appUrl: APP_URL,
  webDir: existsSync(new URL('index.html', webDir)) ? fileURLToPath(webDir) : undefined,
});

app.listen(Number(PORT), (err?: Error) => {
  if (err) throw err; // Express 5 hands a failed listen (such as a busy port) to this callback
  console.log(`listening on ${APP_URL}${clock.demo ? ` (demo clock from ${DEMO_NOW})` : ''}`);
});
services:
  db:
    image: postgres:17-alpine
    environment:
      POSTGRES_USER: bookings
      POSTGRES_PASSWORD: bookings
      POSTGRES_DB: bookings
      TZ: UTC
    # every published port binds to localhost: the db has well-known credentials, so nothing is reachable from the LAN
    ports:
      - "127.0.0.1:5433:5432"
    # test files run in parallel and each race test opens up to 40 connections
    command: ["postgres", "-c", "max_connections=200"]
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U bookings -d bookings"]
      interval: 2s
      retries: 30
    volumes:
      - db-data:/var/lib/postgresql/data

  mailpit:
    image: axllent/mailpit:v1.31.6
    environment:
      TZ: UTC
    ports:
      - "127.0.0.1:8025:8025"
      - "127.0.0.1:1025:1025"

  app:
    build: { context: ., target: runtime }
    # node as PID 1 ignores SIGTERM, so without an init `docker compose down` waits out the 10 s kill timeout
    init: true
    ports:
      - "127.0.0.1:3000:3000"
    environment:
      DATABASE_URL: postgres://bookings:bookings@db:5432/bookings
      SMTP_URL: smtp://mailpit:1025
      APP_URL: http://localhost:3000
      PORT: "3000"
      TZ: UTC
      DEMO_NOW: ${DEMO_NOW:-}
    depends_on:
      db: { condition: service_healthy }
      mailpit: { condition: service_started }
    # lets `docker compose up --wait` return only once the app is serving
    healthcheck:
      test: ["CMD", "wget", "-qO-", "http://localhost:3000/api/slots"]
      interval: 2s
      retries: 30

  test:
    build: { context: ., target: test }
    profiles: [test]
    environment:
      DATABASE_URL: postgres://bookings:bookings@db:5432/bookings
      TZ: UTC
    depends_on:
      db: { condition: service_healthy }

